/* C program */
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int main(){
    pid_t pid = fork();
    if(pid==0){
        execlp("date","date",(char*)NULL);
        _exit(127); // exec failed
    } else if(pid>0){
        int status; waitpid(pid,&status,0);
        if(WIFEXITED(status))
            printf("Child exited with %d\n",WEXITSTATUS(status));
        else
            printf("Child terminated abnormally\n");
    } else {
        perror("fork");
    }
    return 0;
}
The program forks; the child runs the date command, inheriting stdout. The parent waits, extracts the exit code (0 on success), and prints it. This demonstrates proper fork‑exec‑wait handling and avoids zombies.
